CREATE TABLE dbo.Patients (
  PatientId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Patients_Id DEFAULT NEWSEQUENTIALID(), PatientCode VARCHAR(30) NOT NULL,
  FullName NVARCHAR(200) NOT NULL, DateOfBirth DATE NULL, BirthYear SMALLINT NULL, Gender VARCHAR(20) NULL,
  Phone VARCHAR(30) NULL, Email VARCHAR(254) NULL, IdentityNumberEncrypted VARBINARY(MAX) NULL,
  GuardianName NVARCHAR(200) NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_Patients_Status DEFAULT 'ACTIVE',
  MergedIntoPatientId UNIQUEIDENTIFIER NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Patients_CreatedAt DEFAULT SYSUTCDATETIME(),
  CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Patients PRIMARY KEY(PatientId), CONSTRAINT UQ_Patients_Code UNIQUE(PatientCode),
  CONSTRAINT FK_Patients_MergedInto FOREIGN KEY(MergedIntoPatientId) REFERENCES dbo.Patients(PatientId),
  CONSTRAINT CK_Patients_Birth CHECK((DateOfBirth IS NOT NULL AND BirthYear IS NULL) OR (DateOfBirth IS NULL AND BirthYear IS NOT NULL)),
  CONSTRAINT CK_Patients_BirthYear CHECK(BirthYear IS NULL OR BirthYear BETWEEN 1900 AND 2100),
  CONSTRAINT CK_Patients_Status CHECK(Status IN ('ACTIVE','MERGED','BLOCKED'))
);
CREATE TABLE dbo.PatientAliases (
  PatientAliasId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_PatientAliases_Id DEFAULT NEWSEQUENTIALID(), PatientId UNIQUEIDENTIFIER NOT NULL,
  SourcePatientId UNIQUEIDENTIFIER NULL, SourceSystem VARCHAR(80) NOT NULL, SourceIdentifier VARCHAR(100) NOT NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_PatientAliases_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_PatientAliases PRIMARY KEY(PatientAliasId), CONSTRAINT FK_PatientAliases_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId),
  CONSTRAINT UQ_PatientAliases_Source UNIQUE(SourceSystem, SourceIdentifier)
);
CREATE TABLE dbo.PatientAllergies (
  AllergyId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Allergies_Id DEFAULT NEWSEQUENTIALID(), PatientId UNIQUEIDENTIFIER NOT NULL,
  Allergen NVARCHAR(200) NOT NULL, Reaction NVARCHAR(500) NULL, KnowledgeStatus VARCHAR(20) NOT NULL,
  ConfirmedAt DATETIME2 NULL, Source NVARCHAR(200) NOT NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Allergies_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_PatientAllergies PRIMARY KEY(AllergyId), CONSTRAINT FK_Allergies_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId),
  CONSTRAINT CK_Allergies_Knowledge CHECK(KnowledgeStatus IN ('KNOWN','NONE_REPORTED','UNKNOWN'))
);
CREATE TABLE dbo.PatientMedicalHistory (
  MedicalHistoryId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_MedicalHistory_Id DEFAULT NEWSEQUENTIALID(), PatientId UNIQUEIDENTIFIER NOT NULL,
  ConditionCode VARCHAR(80) NULL, Description NVARCHAR(500) NOT NULL, KnowledgeStatus VARCHAR(20) NOT NULL,
  ConfirmedAt DATETIME2 NULL, Source NVARCHAR(200) NOT NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_MedicalHistory_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_PatientMedicalHistory PRIMARY KEY(MedicalHistoryId), CONSTRAINT FK_MedicalHistory_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId),
  CONSTRAINT CK_MedicalHistory_Knowledge CHECK(KnowledgeStatus IN ('KNOWN','NONE_REPORTED','UNKNOWN'))
);
CREATE TABLE dbo.PatientMergeRecords (
  PatientMergeRecordId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_PatientMerges_Id DEFAULT NEWSEQUENTIALID(), SourcePatientId UNIQUEIDENTIFIER NOT NULL,
  TargetPatientId UNIQUEIDENTIFIER NOT NULL, Evidence NVARCHAR(MAX) NOT NULL, RequestedBy UNIQUEIDENTIFIER NOT NULL, ApprovedBy UNIQUEIDENTIFIER NOT NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_PatientMerges_CreatedAt DEFAULT SYSUTCDATETIME(),
  CONSTRAINT PK_PatientMergeRecords PRIMARY KEY(PatientMergeRecordId), CONSTRAINT UQ_PatientMerges_Source UNIQUE(SourcePatientId),
  CONSTRAINT FK_PatientMerges_Source FOREIGN KEY(SourcePatientId) REFERENCES dbo.Patients(PatientId), CONSTRAINT FK_PatientMerges_Target FOREIGN KEY(TargetPatientId) REFERENCES dbo.Patients(PatientId),
  CONSTRAINT FK_PatientMerges_Requester FOREIGN KEY(RequestedBy) REFERENCES dbo.Users(UserId), CONSTRAINT FK_PatientMerges_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId),
  CONSTRAINT CK_PatientMerges_Different CHECK(SourcePatientId <> TargetPatientId AND RequestedBy <> ApprovedBy)
);
CREATE TABLE dbo.Appointments (
  AppointmentId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Appointments_Id DEFAULT NEWSEQUENTIALID(), PatientId UNIQUEIDENTIFIER NOT NULL,
  BranchId UNIQUEIDENTIFIER NOT NULL, DoctorId UNIQUEIDENTIFIER NULL, RoomId UNIQUEIDENTIFIER NULL, StartsAt DATETIME2 NOT NULL, EndsAt DATETIME2 NOT NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_Appointments_Status DEFAULT 'BOOKED', Note NVARCHAR(1000) NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Appointments_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Appointments PRIMARY KEY(AppointmentId), CONSTRAINT FK_Appointments_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId),
  CONSTRAINT FK_Appointments_Branch FOREIGN KEY(BranchId) REFERENCES dbo.Branches(BranchId), CONSTRAINT FK_Appointments_Doctor FOREIGN KEY(DoctorId) REFERENCES dbo.Users(UserId),
  CONSTRAINT FK_Appointments_Room FOREIGN KEY(RoomId) REFERENCES dbo.Rooms(RoomId), CONSTRAINT CK_Appointments_Time CHECK(EndsAt > StartsAt),
  CONSTRAINT CK_Appointments_Status CHECK(Status IN ('BOOKED','CONFIRMED','ARRIVED','COMPLETED','CANCELLED','NO_SHOW'))
);
CREATE TABLE dbo.Visits (
  VisitId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Visits_Id DEFAULT NEWSEQUENTIALID(), VisitCode VARCHAR(30) NOT NULL,
  PatientId UNIQUEIDENTIFIER NOT NULL, AppointmentId UNIQUEIDENTIFIER NULL, BranchId UNIQUEIDENTIFIER NOT NULL, DoctorId UNIQUEIDENTIFIER NOT NULL,
  RoomId UNIQUEIDENTIFIER NULL, VisitType VARCHAR(30) NOT NULL, PaymentType VARCHAR(30) NOT NULL, Status VARCHAR(30) NOT NULL CONSTRAINT DF_Visits_Status DEFAULT 'REGISTERED',
  RegisteredAt DATETIME2 NOT NULL CONSTRAINT DF_Visits_RegisteredAt DEFAULT SYSUTCDATETIME(), ClosedAt DATETIME2 NULL,
  HoldReason NVARCHAR(500) NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Visits_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  OriginalId UNIQUEIDENTIFIER NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_Visits PRIMARY KEY(VisitId), CONSTRAINT UQ_Visits_Code UNIQUE(VisitCode), CONSTRAINT FK_Visits_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId),
  CONSTRAINT FK_Visits_Appointment FOREIGN KEY(AppointmentId) REFERENCES dbo.Appointments(AppointmentId), CONSTRAINT FK_Visits_Branch FOREIGN KEY(BranchId) REFERENCES dbo.Branches(BranchId),
  CONSTRAINT FK_Visits_Doctor FOREIGN KEY(DoctorId) REFERENCES dbo.Users(UserId), CONSTRAINT FK_Visits_Room FOREIGN KEY(RoomId) REFERENCES dbo.Rooms(RoomId),
  CONSTRAINT FK_Visits_Original FOREIGN KEY(OriginalId) REFERENCES dbo.Visits(VisitId), CONSTRAINT CK_Visits_PaymentType CHECK(PaymentType IN ('SELF_PAY','BHTM_GUARANTEE')),
  CONSTRAINT CK_Visits_Status CHECK(Status IN ('REGISTERED','IN_PROGRESS','CLINICAL_COMPLETED','CLOSED','ON_HOLD','CANCELLED','EMERGENCY_TRANSFER'))
);
CREATE TABLE dbo.TreatmentRelationships (
  TreatmentRelationshipId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_TreatmentRelationships_Id DEFAULT NEWSEQUENTIALID(), DoctorId UNIQUEIDENTIFIER NOT NULL,
  PatientId UNIQUEIDENTIFIER NOT NULL, VisitId UNIQUEIDENTIFIER NULL, Source VARCHAR(30) NOT NULL, StartsAt DATETIME2 NOT NULL, EndsAt DATETIME2 NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_TreatmentRelationships_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_TreatmentRelationships PRIMARY KEY(TreatmentRelationshipId), CONSTRAINT FK_TreatmentRelationships_Doctor FOREIGN KEY(DoctorId) REFERENCES dbo.Users(UserId),
  CONSTRAINT FK_TreatmentRelationships_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId), CONSTRAINT FK_TreatmentRelationships_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT CK_TreatmentRelationships_Period CHECK(EndsAt IS NULL OR EndsAt > StartsAt), CONSTRAINT CK_TreatmentRelationships_Source CHECK(Source IN ('VISIT','TREATMENT_PLAN','FOLLOW_UP','EMERGENCY'))
);
CREATE TABLE dbo.VisitStatusHistory (
  VisitStatusHistoryId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_VisitHistory_Id DEFAULT NEWSEQUENTIALID(), VisitId UNIQUEIDENTIFIER NOT NULL,
  FromStatus VARCHAR(30) NULL, ToStatus VARCHAR(30) NOT NULL, Reason NVARCHAR(500) NULL, ChangedAt DATETIME2 NOT NULL CONSTRAINT DF_VisitHistory_At DEFAULT SYSUTCDATETIME(), ChangedBy UNIQUEIDENTIFIER NOT NULL,
  CONSTRAINT PK_VisitStatusHistory PRIMARY KEY(VisitStatusHistoryId), CONSTRAINT FK_VisitHistory_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_VisitHistory_User FOREIGN KEY(ChangedBy) REFERENCES dbo.Users(UserId)
);
CREATE TABLE dbo.EmergencyAccessGrants (
  EmergencyAccessGrantId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_EmergencyAccess_Id DEFAULT NEWSEQUENTIALID(), UserId UNIQUEIDENTIFIER NOT NULL,
  PatientId UNIQUEIDENTIFIER NOT NULL, VisitId UNIQUEIDENTIFIER NULL, Reason NVARCHAR(500) NOT NULL, StartsAt DATETIME2 NOT NULL,
  ExpiresAt DATETIME2 NOT NULL, ApprovedBy UNIQUEIDENTIFIER NULL, ReviewedAt DATETIME2 NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_EmergencyAccess_Status DEFAULT 'ACTIVE',
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_EmergencyAccess_CreatedAt DEFAULT SYSUTCDATETIME(),
  CONSTRAINT PK_EmergencyAccessGrants PRIMARY KEY(EmergencyAccessGrantId), CONSTRAINT FK_EmergencyAccess_User FOREIGN KEY(UserId) REFERENCES dbo.Users(UserId),
  CONSTRAINT FK_EmergencyAccess_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId), CONSTRAINT FK_EmergencyAccess_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_EmergencyAccess_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId), CONSTRAINT CK_EmergencyAccess_Period CHECK(ExpiresAt > StartsAt),
  CONSTRAINT CK_EmergencyAccess_Status CHECK(Status IN ('ACTIVE','EXPIRED','REVOKED','REVIEWED'))
);
